def get_graph_hash():
    graph_path = os.path.join(FRAMEWORK_DIR, 'node_editor', 'graph.json')
    if os.path.exists(graph_path):
        import hashlib
        try:
            with open(graph_path, 'rb') as f:
                return hashlib.md5(f.read()).hexdigest()
        except Exception:
            pass
    return ""

