def get_provider_request_details(provider, ai_config, api_key, system_prompt, user_prompt, stream=False, chat_history=None):
    url = ""
    headers = {
        "Content-Type": "application/json",
        "User-Agent": "NodeEditorFramework/1.0 Mozilla/5.0"
    }
    data = {}
    if chat_history is None:
        chat_history = []

    if provider == "ollama":
        url = ai_config.get("OLLAMA_API_ENDPOINT", "http://localhost:11434/api/generate")
        if not url:
            url = "http://localhost:11434/api/generate"
        if url.endswith("/"):
            url = url[:-1]
        if not url.endswith("/api/generate") and not url.endswith("/api/chat"):
            url = url + "/api/generate"
        
        # Compile chat history into prompt for Ollama
        history_str = ""
        for msg in chat_history:
            role = "User" if msg["role"] == "user" else "Assistant"
            history_str += f"{role}: {msg['content']}\n\n"

        data = {
            "model": ai_config.get("OLLAMA_MODEL", "gemma4:26b"),
            "prompt": f"{system_prompt}\n\n{history_str}User Prompt: {user_prompt}",
            "stream": stream,
            "options": {
                "num_ctx": 128000,
                "num_predict": 32000
            }
        }
    else:
        # Build standard messages list for chat completions
        messages = [{"role": "system", "content": system_prompt}]
        for msg in chat_history:
            messages.append({"role": msg["role"], "content": msg["content"]})
        messages.append({"role": "user", "content": user_prompt})

        if provider == "gemini":
            url = "https://generativelanguage.googleapis.com/v1beta/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("GEMINI_MODEL", "gemini-1.5-flash"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 32000
            }
        elif provider == "gpt":
            url = "https://api.openai.com/v1/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("OPENAI_MODEL", "gpt-4o-mini"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 16000
            }
        elif provider == "claude":
            url = "https://api.anthropic.com/v1/messages"
            headers = {
                "x-api-key": api_key,
                "anthropic-version": "2023-06-01",
                "content-type": "application/json"
            }
            # Claude expects messages list WITHOUT system role (system is a top-level param)
            claude_messages = []
            for msg in chat_history:
                claude_messages.append({"role": msg["role"], "content": msg["content"]})
            claude_messages.append({"role": "user", "content": user_prompt})
            data = {
                "model": ai_config.get("CLAUDE_MODEL", "claude-3-5-sonnet-20241022"),
                "max_tokens": 8192,
                "system": system_prompt,
                "messages": claude_messages,
                "stream": stream
            }
        elif provider == "deepseek":
            url = "https://api.deepseek.com/v1/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("DEEPSEEK_MODEL", "deepseek-chat"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 8192
            }
        elif provider == "openrouter":
            url = "https://openrouter.ai/api/v1/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            headers["HTTP-Referer"] = "http://localhost:8081/"
            headers["X-Title"] = "Cybercore Matrix Builder"
            data = {
                "model": ai_config.get("OPENROUTER_MODEL", "google/gemini-2.0-flash-exp:free"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 32000
            }
        elif provider == "nvidia":
            url = "https://integrate.api.nvidia.com/v1/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("NVIDIA_MODEL", "qwen/qwen3-coder-480b-a35b-instruct"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 32000
            }
        elif provider == "glm":
            url = "https://open.bigmodel.cn/api/paas/v4/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("GLM_MODEL", "glm-4-flash"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 32000
            }
        elif provider == "dough":
            url = "https://dough.id/api/v1/chat/completions"
            headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("DOUGH_MODEL", "deepseek-chat"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 32000
            }
        elif provider == "custom":
            url = ai_config.get("CUSTOM_API_ENDPOINT", "")
            if api_key:
                headers["Authorization"] = f"Bearer {api_key}"
            data = {
                "model": ai_config.get("CUSTOM_MODEL", "custom-model"),
                "messages": messages,
                "stream": stream,
                "max_tokens": 32000
            }
    return url, headers, data

def call_llm_non_stream(provider, ai_config, api_key, system_prompt, user_prompt):
    url, headers, data = get_provider_request_details(provider, ai_config, api_key, system_prompt, user_prompt, stream=False)
    if not url:
        raise ValueError("API Endpoint URL not configured.")
    
    req = urllib.request.Request(
        url,
        data=json.dumps(data).encode('utf-8'),
        headers=headers
    )
    with urllib.request.urlopen(req, timeout=600) as response:
        resp_bytes = response.read()
        resp_json = json.loads(resp_bytes.decode('utf-8'))
        
        if provider == "ollama":
            return resp_json.get('response', '')
        elif provider == "claude":
            return resp_json.get('content', [{}])[0].get('text', '')
        else: # OpenAI compatible
            return resp_json.get('choices', [{}])[0].get('message', {}).get('content', '')

def extract_json_from_text(text):
    if not text:
        return None
    import re
    # Try ```json ... ``` blocks first
    match = re.search(r"```(?:json)?\s*([\{\[].*?[\}\]])\s*```", text, re.DOTALL)
    if match:
        raw = match.group(1)
    else:
        # Try finding raw { ... }
        s, e = text.find('{'), text.rfind('}')
        if s != -1 and e > s:
            raw = text[s:e+1]
        else:
            s, e = text.find('['), text.rfind(']')
            if s != -1 and e > s:
                raw = text[s:e+1]
            else:
                raw = text
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        # Try fixing common issues like trailing commas
        try:
            cleaned = re.sub(r',\s*([}\]])', r'\1', raw)
            return json.loads(cleaned)
        except json.JSONDecodeError:
            return None

